// D43 · Part 4 · 개인정보 가리기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d43_mask.ts
//   글자(로그)에서 전화번호 가운데·이름·말로 읽은 번호를 가리고, 소리(녹음)는 개인정보 구간을 무음 처리하고, 보관 기간이 지난 자료를 지운다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const DIGITS = "공영일이삼사오육칠팔구";

function maskPhone(text: string): string {
  // 전화번호의 가운데를 가림: 010-1234-5678 · 01012345678 · 010 1234 5678 → 010-****-5678, 말로 읽은 번호는 [번호]로
  const num = (m: string): string => { const d = m.replace(/\D/g, ""); return `${d.slice(0, 3)}-****-${d.slice(-4)}`; };
  const t = text.replace(/01\d[- ]?\d{3,4}[- ]?\d{4}/g, num);
  return t.replace(new RegExp(`[${DIGITS}]{3}\\s[${DIGITS}]{3,4}\\s[${DIGITS}]{4}`, "g"), "[번호]");
}

const maskName = (text: string): string => text.replace(/(이름은 )([가-힣])([가-힣]+)/g, (_m, a: string, b: string, c: string) => a + b + "○".repeat(c.length)); // '이름은 김민준' → '이름은 김○○' (성만 남김)

const deleteOld = (records: { day: number }[], today: number, keepDays: number): { day: number }[] => records.filter((r) => today - r.day <= keepDays); // 보관 기간(일)이 지난 자료를 지우고 남은 것만

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const phones = ["010-1234-5678", "01012345678", "010 1234 5678"];
for (const s of phones) console.log(`${s} → ${maskPhone(s)}`);
check(phones.every((s) => maskPhone(s) === "010-****-5678"), "어떤 쓰기든 010-****-5678 로 가려야 해요.");

const log = "제 이름은 김민준 입니다. 공일공 이삼사오 육칠팔구 입니다.";
const masked = maskName(maskPhone(log));
console.log(masked);
check(masked === "제 이름은 김○○ 입니다. [번호] 입니다." && maskPhone("내일 오전 열 시에 예약해 주세요") === "내일 오전 열 시에 예약해 주세요", "이름은 성만 남기고, 말로 읽은 번호는 [번호]로, 개인정보 없는 말은 그대로여야 해요.");

// 소리: 개인정보를 말한 구간(초)을 무음으로 (합성 신호로 흉내 · 실제 구간은 받아쓰기 시각에서 얻음)
const y = Float32Array.from({ length: 3 * SR }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 440 * i) / SR));
const out = y.slice();
const spans: [number, number][] = [[1.0, 1.8]];
for (const [a, b] of spans) out.fill(0, Math.floor(a * SR), Math.floor(b * SR));
const inside = out.slice(SR, Math.floor(1.8 * SR));
const outsideSame = out.every((v, i) => (i >= SR && i < Math.floor(1.8 * SR) ? true : v === y[i]));
console.log(`무음 처리한 길이 ${(inside.length / SR).toFixed(1)}초 / 전체 ${y.length / SR}초`);
check(inside.every((v) => v === 0) && outsideSame, "구간 안은 완전히 0, 밖은 그대로여야 해요.");

const records = [{ id: 1, day: 0 }, { id: 2, day: 20 }, { id: 3, day: 31 }];
const kept = deleteOld(records, 40, 30).map((r) => (r as { id: number; day: number }).id);
console.log("보관 30일, 오늘 40일째 → 남은 자료", JSON.stringify(kept));
check(JSON.stringify(kept) === "[2,3]", "40일 전(0일째) 자료만 지워야 해요.");

